/// <summary>
/// PaffH 24.09.25
/// </summary>
/// <returns>dirPartyTable</returns>
private DirPartyTable getDirPartyTable()
{
    DirPartyTable dirPartyTable;
    if (this.DirPartyTableManual)
    {
        dirPartyTable = DirPartyTable::findRec(this.DirPartyTableManual);
    }
    else if (this.ProspectProspectId)
    {
        dirPartyTable = DirPartyTable::findByNum(this.ProspectProspectId);
    }
    return DirPartyTable;
}

/// <summary>
/// PaffH 24.09.25
/// </summary>
/// <returns>Name 1</returns>
[SysClientCacheDataMethod(true)]
public display NDXLogisticsLocationName1 dispName1()
{
    DirPartyTable dirPartyTable = this.getDirPartyTable();

    if (dirPartyTable)
    {
        return LogisticsPostalAddress::findByLocation(dirPartyTable.PrimaryAddressLocation).NDXLogisticsLocationName1;
    }
    else
    {
        return this.Name1;
    }
}

