/// <summary>
/// PaffH 23.09.25
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case (fieldNum(NDXBVEMailRequestPlaner, DirPartyTableManual)) :
            NDXBVEmailRequestRoleIdentificationContract::construct(this).checkIdentification();
            break;
    }
}

/// <summary>
/// PaffH 23.09.25
/// </summary>
public void initValue()
{
    super();

    this.Active = NoYes::Yes;
}

/// <summary>
/// PaffH 24.09.25
/// insert Planer (manual)
/// </summary>
/// <param name = "_guiId">NDXGUID</param>
/// <returns>NDXBVEMailRequestPlaner</returns>
public static NDXBVEMailRequestPlaner insertManual(NDXGUID _guiId)
{
    NDXBVEMailRequestPlaner nDXBVEMailRequestPlaner;
    select firstonly nDXBVEMailRequestPlaner order by IdentifierLine desc where nDXBVEMailRequestPlaner.IdentifierGUID == _guiId;
    Line identifierLineNew = nDXBVEMailRequestPlaner.IdentifierLine + 1;

    nDXBVEMailRequestPlaner.clear();
    nDXBVEMailRequestPlaner.initValue();
    nDXBVEMailRequestPlaner.IdentifierGUID = _guiId;
    nDXBVEMailRequestPlaner.IdentifierLine = identifierLineNew;
    nDXBVEMailRequestPlaner.Manual = NoYes::Yes;
    NDXBVEmailRequestRoleIdentificationContract::construct(nDXBVEMailRequestPlaner).checkIdentification();
    if (nDXBVEMailRequestPlaner.validateWrite())
    {
        nDXBVEMailRequestPlaner.insert();
    }
    return nDXBVEMailRequestPlaner;
}

/// <summary>
/// PaffH 24.09.25
/// delete manual record
/// </summary>
/// <returns>deleted ?</returns>
public boolean deleteManual()
{
    if (this.Manual == NoYes::Yes)
    {
        if (this.validateDelete())
        {
            ttsbegin;
            this.delete();
            ttscommit;
            return true;
        }
    }
    else if (this.Active)
    {
        this.Active = NoYes::No;
        if (this.validateWrite())
        {
            ttsbegin;
            this.update();
            ttscommit;
        }
    }
    return false;
}

/// <summary>
/// PaffH 27.10.25
/// </summary>
/// <param name = "_recId">RecId</param>
/// <returns>rec exists</returns>
public static boolean exists(RecId _recId)
{
    return _recId > 0 &&
        (select firstonly RecId from NDXBVEMailRequestPlaner where NDXBVEMailRequestPlaner.RecId == _recId).RecId > 0;
}
